script.inlineScript:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const {
		selectionProps,
		current
	} = api.data.list_controller;
	const {
		elementId,
		context
	} = event;
	const {
		action
	} = context.item.value;

	return {
		selectProps: selectionProps,
		table: current.table,
		query: current.query,
		action: action
	};
}

